import java.util.HashMap;
import java.util.Map;

public class PoorPerformance {
    private final Map<String, String> map = new HashMap<>();

    // BAD: Coarse-grained locking
    public synchronized String get(String key) {
        return map.get(key);
    }

    public synchronized void put(String key, String value) {
        map.put(key, value);
    }

    // BAD: Non-volatile field without synchronization
    private boolean flag = false;
    private int data = 0;

    public void writer() {
        data = 42;
        flag = true; // Other threads might not see this change
    }

    public void reader() {
        int attempts = 0;
        while (!flag && attempts++ < 1_000) {
            Thread.onSpinWait();
        }
        if (!flag) {
            throw new IllegalStateException("Update was not visible before the bounded wait ended");
        }
        // Might see stale data
        System.out.println("Data: " + data);
    }
}

